NAV = ["Kom igång", "Högar och datum", "Genomgångar", "Synkronisering", "Importer och säkerhetskopior", "Gratis och betald", "Felsökning", "Kontakt"]
TRB = "Felsökning"
CONTACT = "Kontakt"
NOTE = "Den här sidan är en översättning av den engelska <en>hjälpsidan</en>. Om de skiljer sig åt gäller den engelska versionen."
INTRO = "En kort manual för en liten app. Ny här? Börja högst upp. Fungerar något inte? Gå till <t>Felsökning</t> och hjälper inte det, <c>skriv till mig</c>."
G = {
0: "Dina första uppgifter",
1: "Börja med en handfull riktiga uppgifter. Projekt och kategorier kan vänta tills du behöver dem.",
2: "1. Skriv ner något",
3: "Tryck på <strong>+</strong>, skriv uppgiften och spara. Den hamnar i ”{inbox}”, där saker väntar tills du har bestämt vad du ska göra med dem. En uppgift behöver inget mer: varken projekt eller datum.",
4: "2. Ge den en plats",
5: "Tryck på en uppgift (klicka, på en Mac) för att se vad du kan göra med den. Att flytta den är det viktigaste. Lägg det du arbetar med i ”<strong>{now}</strong>”. Den kan ligga kvar i dagar eller veckor; inget knuffar bort den. ”<strong>{next}</strong>” är det du tar upp härnäst, ”<strong>{later}</strong>” är för det du vill spara men inte rör, och ”<strong>{waiting}</strong>” är för det som sitter fast i väntan på någon annan.",
6: "<a href=\"#stacks-and-dates\">Nästa avsnitt</a> förklarar högarna ordentligt.",
7: "3. Håll ihop det som hör ihop",
8: "Välj <strong>{edit_plain}</strong> bland en uppgifts åtgärder för att ändra detaljerna och lägga till anteckningar.",
9: "Ett <strong>projekt</strong> samlar uppgifterna i ett och samma arbete: en resa, en kurs, en kund. En <strong>kategori</strong> är en bred del av ditt liv, som Arbete eller Hem. En <strong>grupp</strong> samlar projekt. Ett projekt hör till en kategori och kan ligga i en grupp, och ändrar du det ena eller det andra gäller det för varje uppgift i projektet. En uppgift utan projekt kan ändå ha en kategori.",
10: "4. Hitta runt",
11: "Sökningen och filtret hjälper dig att fokusera på ett projekt eller en kategori. På en Mac, och på en iPad i liggande läge, visar ett sidofält kategorier, grupper och projekt. Från filtret kan du byta namn på dem och ändra ordningen.",
12: "Under <strong>{more} → {appearance}</strong> väljer du Automatiskt, Ljust eller Mörkt. Automatiskt följer din enhet.",
13: "5. Avsluta",
14: "Tryck på cirkeln när arbetet är klart. En klar uppgift lämnar högarna men försvinner inte: <strong>{more} → {timeline}</strong> listar allt du har blivit klar med, per dag, och du kan öppna en uppgift som du kryssade av för tidigt.",
15: "När listorna börjar kännas gamla, prova en <a href=\"#reviews\">genomgång</a>.",
16: "<strong>Prova det här.</strong> Lägg till ”Planera trädgården”. Lägg den i ”{now}” medan du samlar idéer. När du ber en hantverkare om en offert flyttar du den till ”{waiting}” och ställer in en påminnelse för den dag du vill följa upp. Samma uppgift från början till slut.",
17: "Var en uppgift bor, och när du tittar på den",
18: "En hög säger vad du tänker göra med en uppgift. Ett datum säger när du vill bli påmind. DayHand håller de två isär med avsikt.",
19: "De fem högarna",
20: "{inbox}",
21: "Det du precis har skrivit ner och ännu inte placerat.",
22: "{now}",
23: "Det du arbetar aktivt med, även om det tar flera dagar.",
24: "{next}",
25: "Det du tar upp när du har utrymme. Det betyder inte i morgon.",
26: "{later}",
27: "Idéer och planer du vill spara och ännu inte rör.",
28: "{waiting}",
29: "Arbete som behöver ett svar, en leverans, ett beslut eller någon annans del innan du kan gå vidare. Annorlunda än ”{later}”: här skulle du gå vidare om du kunde.",
30: "Ett datum flyttar aldrig en uppgift. Att tiden går ändrar inte var den ligger; du bestämmer när den flyttas.",
31: "Här är en uppgift under en vecka. På måndagen lägger du till ”Förbereda presentationen”, med en påminnelse till tisdag och en deadline på fredag. På tisdagen säger påminnelsen att du ska börja, så du flyttar den till ”{now}”. Något mer akut kommer emellan, så den går till ”{later}” med en ny påminnelse till onsdag. På onsdagen är den tillbaka i ”{now}”. På torsdagen skickar du ett utkast till en kollega och parkerar den i ”{waiting}”. På fredagen kommer svaret, du blir klar och kryssar av den. En uppgift, en deadline som aldrig ändrades, och ingenting var någonsin ”försenat”.",
32: "Påminnelser: titta på det här igen",
33: "Välj <strong>{remind_me}</strong> bland en uppgifts åtgärder, eller ställ in en i redigeraren. <strong>{change_reminder}</strong> väljer en annan dag och <strong>{clear_reminder}</strong> tar bort den.",
34: "En påminnelse går av klockan <strong>9 den dag du valde</strong>, förutsatt att aviseringar är tillåtna för DayHand. Ställer du in en för idag efter klockan 9 finns inget kvar att avfyra: uppgiften markeras som att den ska göras nu och ingen avisering följer. Datumväljaren säger till när det händer. (Påminnelser som skapades av äldre versioner kan behålla den tid de hade.)",
35: "Tryck på en avisering så öppnar DayHand den uppgiften. Att avfärda den är inget svar; påminnelsen väntar kvar i appen. Du svarar på den med <strong>{keep_here}</strong> (den ligger i rätt hög, tack), genom att flytta uppgiften, slutföra den eller välja en annan dag.",
36: "Färger, flaggan och märket",
37: "<strong>Orange kant:</strong> påminnelsen kommer inom de närmaste tre dagarna.",
38: "<strong>Röd kant:</strong> påminnelsen är i dag, eller har redan passerat. Det betyder ”du ville titta på det här”, inte ”du är sen”.",
39: "<strong>Flaggan i appen:</strong> samlar varje uppgift med röd eller orange kant, i vilken hög som helst. Siffran räknar de röda.",
40: "<strong>Märket på appikonen:</strong> räknar påminnelser som har kommit och som du inte har svarat på.",
41: "Så flaggan och märket kan skilja sig åt, och det är okej. Svara på en påminnelse med ”{keep_here}” och märket minskar, medan uppgiften behåller sin röda kant och ligger kvar i flaggan tills du ändrar eller tar bort datumet.",
42: "Deadlines: klart till dess",
43: "Lägg till en deadline i redigeraren när det finns en verklig mållinje: en inlämning, en förnyelse, en leverans. För att lägga till en ny ställer du först in en påminnelse, och deadlinefältet dyker upp efteråt. Om du senare tar bort påminnelsen finns en deadline du redan hade kvar, synlig och redigerbar.",
44: "En deadline skickar ingen avisering och flyttar ingenting. Den står bara på uppgiften. Ställ in påminnelsen tillräckligt tidigt för att du ska hinna göra något.",
45: "Ingen avisering? Se <a href=\"#notifications\">vad du kan kontrollera</a>.",
46: "Genomgångar",
47: "Öppna <strong>{more} → {review}</strong> och välj en hjälpare. Var och en ställer en enda fråga om en enda uppgift eller ett enda projekt, så att du bestämmer dig i stället för att scrolla genom en lång lista.",
48: "Gå igenom uppgifter",
49: "{rv_inbox}",
50: "Var hör det här hemma? Flytta nya uppgifter till den hög som passar, eller låt dem ligga om du inte är redo.",
51: "{rv_now}",
52: "Arbetar jag fortfarande aktivt med det här? Behåll det som är aktivt, flytta det som har ändrats, slutför det som är klart.",
53: "{rv_waiting}",
54: "Kan det här gå vidare? Behåll det som verkligen är blockerat, ta tillbaka det som inte är det, eller ställ in en påminnelse för att följa upp.",
55: "{rv_next_later}",
56: "Är det här fortfarande relevant? Lyft fram det som betyder något och släpp det som inte gör det.",
57: "{rv_all}",
58: "”{inbox}”, ”{now}”, ”{waiting}”, sedan ”{next}” och ”{later}”, i ett svep. En uppgift som du flyttar under svepet kommer inte tillbaka i samma svep.",
59: "Hjälparen visar uppgiften och hur länge den har legat i sin hög. Låt den ligga kvar, flytta den, redigera den, slutför den eller ta bort den. Högknapparna sitter på samma ställe från en uppgift till nästa, så att tummen lär sig dem.",
60: "Du kan avbryta mitt i och komma tillbaka. Var du är sparas bara på den enheten; en annan enhet börjar sitt eget svep. Uppgifter som kommer in under tiden väntar på nästa svep.",
61: "<strong>En genomgång är ett beslut, inte en deadline.</strong> ”{keep_in_now}” är ett fullt giltigt svar, även för en uppgift som har legat där i en månad.",
62: "Gå igenom projekt",
63: "<strong>{review_projects}</strong> ställer en fråga per projekt: <em>finns det en tydlig väg framåt?</em> Du ser uppgifterna per hög, med kategorin och gruppen.",
64: "<strong>{looks_right}:</strong> bra, gå vidare.",
65: "<strong>{add_task}:</strong> skriv ner det steg som saknas, med det här projektet redan valt.",
66: "<strong>{review_these}:</strong> gå igenom det här projektets uppgifter en i taget.",
67: "<strong>{edit_project}:</strong> ändra namn, kategori eller grupp.",
68: "Efter att du har lagt till, redigerat eller gått igenom kommer du tillbaka till samma projekt. Vinkeln uppe till vänster går tillbaka till projektet du just lämnade, och krysset avslutar genomgången.",
69: "Projekt med ofärdigt arbete kommer först. Projekt där inget mer återstår kommer efter, så att du kan arkivera dem. Arkiverade projekt hoppas över, och uppgifter utan projekt visas i stället i uppgiftsgenomgångarna.",
70: "Att arkivera ett projekt som fortfarande har öppna uppgifter ber dig slutföra dem först. Arkivering är för avslutat arbete, inte ett sätt att försätta ett projekt i dvala; använd ”{later}” för det.",
71: "Blicka tillbaka",
72: "<strong>{more} → {timeline}</strong>, och ett enskilt projekts Historik, visar vad du har blivit klar med. De är skilda från hjälparna, som handlar om arbete som fortfarande är öppet.",
73: "Synkronisering",
74: "DayHand delar dina uppgifter via en fil i din egen iCloud Drive. Det finns inget DayHand-konto och ingen server. På en enda enhet behöver du inget av detta.",
75: "Den första enheten",
76: "Kontrollera att iCloud Drive är på.",
77: "Öppna <strong>{more} → {sync} → {create_sync}</strong>.",
78: "Spara filen i en mapp i iCloud Drive som du hittar igen.",
79: "Ge iCloud en stund att ladda upp den innan du ställer in nästa enhet.",
80: "Varje annan enhet",
81: "Logga in med samma Apple-konto och kontrollera att filen har laddats ner.",
82: "Öppna <strong>{more} → {sync} → {use_existing}</strong>.",
83: "Välj <strong>{merge_with}</strong>, som behåller uppgifterna på båda sidor.",
84: "Välj <strong>samma fil</strong> som du skapade på den första enheten. Skapa inte en andra fil med samma namn; två filer med ett namn är två olika filer.",
85: "Titta på dina uppgifter och synkroniseringsstatusen på båda enheterna.",
86: "<strong>Att ersätta är något annat.</strong> ”{replace_device}” kastar bort det som finns på den här enheten och tar i stället uppgifterna från filen. Om du kan vilja ha tillbaka den nuvarande listan, gör först en <a href=\"#backups\">säkerhetskopia</a>.",
87: "DayHand kontrollerar att filen du väljer verkligen är en DayHand-fil. Ett kalkylblad, någon annans JSON eller ett foto avvisas, eftersom synkroniseringen skriver till filen och skulle skriva över den.",
88: "Dag för dag",
89: "Varje enhet har sin egen kopia, så du kan arbeta offline. Ändringar möts via filen när iCloud har levererat den och DayHand har läst den. Det kan ta en stund, och en stängd app har ingen brådska. Räkna inte med att det går direkt.",
90: "Undvik att redigera samma uppgift på två enheter medan båda är offline. Om två versioner av en uppgift krockar vinner den senaste ändringen. DayHand slår inte ihop två ändringar av samma titel.",
91: "När enheterna är oense",
92: "Titta på <strong>{more} → {sync}</strong> på varje enhet. ”{not_syncing}” betyder att ingen fil är ansluten där.",
93: "Kontrollera att båda använder samma fil på samma plats. Samma namn räcker inte.",
94: "Kontrollera att iCloud Drive är anslutet och att filen har laddats ner färdigt, i Filer eller i Finder.",
95: "Öppna DayHand på båda enheterna och tryck på <strong>{sync_now}</strong>. Läs raden under knappen.",
96: "Om du har flyttat eller bytt namn på filen och en enhet har tappat bort den, säkerhetskopiera den enheten, sluta använda den gamla länken och välj rätt fil igen, med Slå ihop.",
97: "Koppla från",
98: "<strong>{stop_using}</strong> kopplar från den här enheten. Uppgifterna finns kvar. Om du bara vill titta på en sparad kopia en gång, utan att ansluta något, använd i stället <a href=\"#restore\">{restore_file}</a>.",
99: "Sitter du fortfarande fast? <a href=\"#troubleshooting\">Berätta för mig</a>, och säg vad synkroniseringsstatusen visar på varje enhet.",
100: "Importer, exporter och säkerhetskopior",
101: "Dina uppgifter är dina: ta in dem, ta ut dem och få tillbaka dem. En import är en engångskopia. DayHand förblir inte ansluten till appen de kom från.",
102: "Från Apples Påminnelser",
103: "Öppna <strong>{more} → {tasks} → {import_reminders}</strong>.",
104: "Tillåt åtkomst till Påminnelser. Apple erbjuder bara ”full åtkomst” för att läsa listor. DayHand läser dem och ändrar dem aldrig.",
105: "Välj listorna, högen uppgifterna ska hamna i, ett projekt eller en kategori och om förfallodatum ska följa med.",
106: "Titta på förhandsvisningen och bekräfta sedan.",
107: "Ett förfallodatum blir en DayHand-påminnelse klockan 9, inte en deadline, och det ursprungliga datumet och klockslaget finns kvar i Anteckningar. Återkommande påminnelser hoppas över. Deluppgifter, taggar, bilagor och regler i smarta listor tas inte med. Anteckningar, länkar, platser och prioriteter kommer med som text där de finns.",
108: "En säkerhetskopia görs först. Importera samma listor igen på samma enhet så hoppas redan importerade uppgifter över, även de du har tagit bort. På en annan enhet, eller efter att du har återställt ditt konto, kan du få dubbletter.",
109: "Från Todoist",
110: "Exportera dina projekt som CSV-filer i Todoist.",
111: "Öppna <strong>{more} → {tasks} → {import_todoist}</strong> och välj en eller flera av de filerna.",
112: "För varje fil väljer du hög, projekt och kategori, och tittar på datumalternativen.",
113: "Läs förhandsvisningen och eventuella varningar och importera sedan.",
114: "Todoists projektexport innehåller inte slutförda uppgifter. Datum som den känner igen blir påminnelser klockan 9; deadlines förblir deadlines. Beskrivningar, kommentarer och de andra detaljer den kan läsa hamnar i Anteckningar. Deluppgifter blir uppgifter i egen rätt, med förälder och sektion noterade. Bilagor laddas inte ner. Återkommande scheman skapas inte på nytt. Ett datum som DayHand inte förstår flaggas för dig; om du importerar uppgiften ändå finns den ursprungliga datumtexten kvar i Anteckningar.",
115: "En säkerhetskopia görs först. Att importera en oförändrad fil med samma namn hoppar över rader som redan importerats. Redigerar eller döper du om exporten kan du få dubbletter.",
116: "<strong>Se upp med aviseringarna.</strong> Apples Påminnelser och Todoist fortsätter skicka sina egna aviseringar, och en framtida påminnelse som du importerar säger också till från DayHand. Bestäm vilken app som får störa dig.",
117: "DayHand-CSV",
118: "<strong>{more} → {tasks} → {export_csv}</strong> sparar en portabel kopia. <strong>{import_csv}</strong> erbjuder <strong>{add_existing}</strong>, som slår ihop en DayHand-CSV med ditt arbete, eller <strong>{replace_all}</strong>, som först rensar de nuvarande uppgifterna. Tänk efter två gånger innan du väljer det andra.",
119: "För Todoist-filer, använd Todoist-importen. CSV-filer från andra appar matchar inte DayHands format. Vill du förbereda en fil själv, exportera först några uppgifter och kopiera strukturen.",
120: "Säkerhetskopior",
121: "Under <strong>{more} → {backups}</strong> trycker du på <strong>{backup_now}</strong> innan något större. DayHand gör också egna, de dagar du öppnar appen, i några få roterande platser: i går, i förrgår och ungefär en vecka tillbaka. De är ett skyddsnät, inte ett arkiv. En andra manuell säkerhetskopia samma dag ersätter den första.",
122: "För att behålla en kopia där du vill, använd åtgärden <strong>{share}</strong> på en säkerhetskopia. På en Mac högerklickar du på en säkerhetskopia för Återställ, Dela och Ta bort. På en iPhone eller iPad håller du nere. Svep fungerar också.",
123: "Återställa",
124: "Om du kan vilja ha tillbaka de nuvarande uppgifterna, gör först en säkerhetskopia eller exportera dem.",
125: "Tryck på en säkerhetskopia i listan, eller välj <strong>{restore_file}</strong> och välj vilken DayHand-fil som helst.",
126: "Läs de två siffrorna i bekräftelsen: uppgifterna här och uppgifterna i filen. Att återställa ersätter de nuvarande uppgifterna och för även tillbaka kategorierna och projekten.",
127: "Bekräfta bara om det är den kopia du vill ha.",
128: "<strong>{restore_file} läser bara filen.</strong> Den ansluter den inte för synkronisering. Om du synkroniserar förblir det som det var, så det du återställer följer med till dina andra enheter. För att titta på en kopia för sig, sluta synkronisera först.",
129: "För en löpande koppling till en delad fil, se <a href=\"#sync\">Synkronisering</a>.",
130: "Gratis och betald",
131: "Planen är en gratis app med ett enda köp som låser upp resten. Ingen prenumeration.",
132: "<strong>Hur det ser ut nu.</strong> Det här är en beta, och allt är upplåst. Köpet, provperioden på 30 dagar och Återställ köp är inte byggda ännu. Det som följer är planen, så att du vet vad du kan vänta dig. En testbrytare i betan låter mig prova gränserna på mina egna enheter.",
133: "Gratis",
134: "Obegränsat med uppgifter, kategorier och grupper, upp till <strong>tre aktiva projekt</strong> och de <strong>senaste 30 dagarna</strong> av slutförda uppgifter. Genomgångarna, anteckningarna, påminnelserna, deadlines, synkroniseringen, importerna, exporterna och säkerhetskopiorna ingår alla. Jag vill inte ha de användbara delarna bakom en vägg.",
135: "Upplåsningen",
136: "Ett köp, en gång: obegränsat med aktiva projekt och hela historiken över slutförda uppgifter, på iPhone, iPad och Mac, med samma Apple-konto. Jag skriver priset här när det finns.",
137: "Vid gränsen",
138: "Arkiverade projekt räknas inte, så att arkivera ett färdigt projekt frigör en plats, och att återta ett tar en. Att skriva ner en uppgift blockeras aldrig. Ett projekt du redan har förblir läsbart och redigerbart, även om en import tar dig över tre.",
139: "Slutförda uppgifter som är äldre än 30 dagar är bara dolda i {timeline}. Sökningen hittar dem fortfarande, och de finns kvar i dina säkerhetskopior och CSV-exporter. Ingenting tas någonsin bort för att du inte har betalat.",
140: "Provperioden",
141: "Jag planerar en provperiod på 30 dagar som du själv startar. När den tar slut går appen tillbaka till den gratis versionen. Ingen debitering, och ingenting sker automatiskt. Den finns inte ännu, och inte heller Återställ köp. Jag förklarar båda här när de kommer.",
}
